CREATE OR REPLACE FUNCTION public.dye_boil_refusal(p_world uuid, p_uid uuid, p_recipe text, p_item text, p_have integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case when p_have * dye_grams_of(p_item) >= dye_boil_grams(p_world, p_uid, p_recipe) then null
              else 'Need ' || dye_kg_said(dye_boil_grams(p_world, p_uid, p_recipe)) || ' kg of '
